#define RES iResolution

float PI = 3.14159265358979;
bool CLAMP = false;
float point_size = 0.007;

float HUE_OFFSET = 100.0; /* degrees */

vec2 P_C_GAMUT_R = vec2(0.6915, 0.3083);
vec2 P_C_GAMUT_G = vec2(0.17, 0.7);
vec2 P_C_GAMUT_B = vec2(0.1532, 0.0475);
vec2 P_C_WP = vec2(0.3127, 0.3290);


mat3 sRGB_GAMUT_RGB_TO_XYZ = mat3(
    0.412453, 0.212671, 0.019334,
    0.357580, 0.715160, 0.119193,
    0.180423, 0.072169, 0.950227
);

mat3 P_C_GAMUT_RGB_TO_XYZ = mat3(
    0.6019868, 0.2683912, 0.0001741,
    0.1637688, 0.6743420, 0.1252349, 
    0.1847003, 0.0572667, 0.9636487
);

vec4 GCORR = vec4(
    0.42,      // gamma
    0.0031308, // transition
    12.92,     // slope
    0.055      // offset
);

mat3x2 GAMUT_TO_NORMAL = mat3x2(
    1.73807977, -0.75188987,
    0.84007744,  1.55192605,
   -0.88352777,  0.04147304
);

mat3x2 NORMAL_TO_GAMUT = mat3x2(
    0.466, 0.226,
   -0.252, 0.522,
    0.422, 0.178
);

bool draw_point(vec2 p, vec2 uv) {
    return distance(p, uv) < point_size;
}

float gammaTransform(float x) {
    return x <= GCORR.y ? 
        GCORR.z * x : 
        (1.0 + GCORR.w) * pow(x, GCORR.x) - GCORR.w;
}

vec3 colorFromXYZ(float x, float y, float z, int gamut) {
    mat3 matrix;
    if (gamut == 1) matrix = P_C_GAMUT_RGB_TO_XYZ;
    if (gamut == 2) matrix = sRGB_GAMUT_RGB_TO_XYZ;

    vec3 rgb = inverse(matrix) * vec3(x, y, z);
     return vec3(
         gammaTransform(rgb.r),
         gammaTransform(rgb.g),
         gammaTransform(rgb.b)
    );
}

vec3 colorFromXYY(float x, float y, float Y, int gamut) {
    float z = 1.0 - x - y;
    return colorFromXYZ((Y/y)*x, Y, (Y/y)*z, gamut);
}

float findMaximumY(float x, float y, int gamut) {
    float bri = 1.0;
    vec3 color;
    float _max;
    for (int i=0; i<10; i++) {
        color = colorFromXYY(x, y, bri, gamut);
        _max = max(max(color.r, color.g), color.b);
        bri = bri / _max;
    }
    return bri;
}

vec3 xy_to_rgb(float x, float y, int gamut) {
    float maxY = findMaximumY(x, y, gamut);
    float bri = 250.0;
    return colorFromXYY(x, y, maxY * bri / 255.0, gamut);
}

vec3 hsv_to_rgb1(float h, float s, float v) {
    if (h == 1.0) h = 0.0;
    float i = floor(h * 6.0);
    float f = h * 6.0 - i;
    float p = v * (1.0 - s);
    float q = v * (1.0 - f*s);
    float t = v * (1.0 - (1.0-f)*s);
    switch (int(i) % 6) {
        case 0: return vec3(v, t, p);
        case 1: return vec3(q, v, p);
        case 2: return vec3(p, v, t);
        case 3: return vec3(p, q, v);
        case 4: return vec3(t, p, v);
        case 5: return vec3(v, p, q);
    }
}

vec3 hsv_to_rgb2(float h, float s, float v) {
    h = h * 360.0;
    float c = v*s;
    float _min = v - c;

    float hp = (h >= 300.0) ? (h - 360.0) / 60.0 : h / 60.0;
    if (hp >= -1.0 && hp < 1.0)
        return vec3(
            v,
            hp < 0.0 ? _min : (_min + hp*c),
            hp < 0.0 ? (_min - hp*c) : _min
        );

    if (hp >= 1.0 && hp < 3.0)
        return vec3(
            hp < 2.0 ? (_min - (hp - 2.0)*c) : _min,
            v,
            hp < 2.0 ? (_min) : (_min + (hp - 2.0)*c)
        );

    if (hp >= 3.0 && hp < 5.0)
        return vec3(
            hp < 4.0 ? _min : (_min + (hp - 4.0)*c),
            hp < 4.0 ? _min - (hp - 4.0)*c : _min,
            v
        );
}

float pc_to_angle(vec2 pc) {
    float theta = atan(pc.y, pc.x);
    if (theta < 0.0) theta = theta + 2.0*PI;
    return theta / (2.0*PI);
}

vec3 clamp_rgb(vec3 rgb) {
    return vec3(
        clamp(rgb.r, 0.0, 1.0),
        clamp(rgb.g, 0.0, 1.0),
        clamp(rgb.b, 0.0, 1.0)
    );
}

float cut_gamut(vec3 rgb) {
    if (rgb.r < 0.0 || rgb.r > 1.0 ||
        rgb.g < 0.0 || rgb.g > 1.0 ||
        rgb.b < 0.0 || rgb.b > 1.0)
        return 0.0;
    return 1.0;
}

float cut_circle(vec2 p, vec2 center, float radius) {
    return step(distance(p, center), radius);
}

float vangle(vec2 a, vec2 b) {
    return acos(dot(a, b) / length(a) / length(b));
}

vec2 bisector(vec2 a, vec2 b) {
    return length(a)*b + length(b)*a;
}

vec2 line_from_points(vec2 p1, vec2 p2) {
    float m = (p1.y - p2.y) / (p1.x - p2.x);
    float b = p2.y - m * p2.x;
    return vec2(m, b);
}

vec2 intersection(vec2 line1, vec2 line2) {
    float x = (line2.y - line1.y) / (line1.x - line2.x);
    float y = line1.x*x + line1.y;
    return vec2(x, y);
}

void mainImage(out vec4 rgba, in vec2 p) {    
    float radius = distance(P_C_WP, P_C_GAMUT_B);
    vec2 uv = p / RES.y;
    float width = RES.x / RES.y;
    uv.x -= width/2.0;
    vec2 p_gamut = NORMAL_TO_GAMUT * vec3(uv, 1.0); 
    vec3 c;
    c = xy_to_rgb(p_gamut.x, p_gamut.y, 1);
    c *= cut_gamut(xy_to_rgb(p_gamut.x, p_gamut.y, 1));
    rgba = vec4(c, 1.0);
}
